--- a/src/main/java/clinic/stats/RoomLoad.java
+++ b/src/main/java/clinic/stats/RoomLoad.java
@@ -7,14 +7,27 @@ public class RoomLoad {

     private static final int WORKING_MINUTES = 600;

-    public double percent(int busyMinutes) {
-        return 0.0;
+    public double percent(int busyMinutes) {
+        if (busyMinutes <= 0) {
+            return 0.0;
+        }
+
+        return (busyMinutes / WORKING_MINUTES) * 100.0;
+    }
+
+    public String label(int busyMinutes) {
+        return Math.round(percent(busyMinutes)) + "%";
     }

     public boolean isOverbooked(int busyMinutes) {
         return busyMinutes > WORKING_MINUTES;
     }
 }
